WITH ALL_EVENTS AS (
    SELECT MATCH_HKEY, DATE_SUBMITTED_TO_AE AS FACT_DATE, 'SUBMITTED_TO_AE' AS EVENT_TYPE, DIVISION, DOMAIN, SEGMENT, _AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
    FROM {{ ref('sat_bh4sf_match_bvv_curr') }}
    WHERE DATE_SUBMITTED_TO_AE IS NOT NULL

    UNION ALL

    SELECT MATCH_HKEY, DATE_SUBMITTED_TO_HM AS FACT_DATE, 'SUBMITTED_TO_HM' AS EVENT_TYPE, DIVISION, DOMAIN, SEGMENT, _AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
    FROM {{ ref('sat_bh4sf_match_bvv_curr') }}
    WHERE DATE_SUBMITTED_TO_HM IS NOT NULL

    UNION ALL

    SELECT MATCH_HKEY, FIRST_CLIENT_INTERVIEW_DATE AS FACT_DATE, 'FIRST_CLIENT_INTERVIEW' AS EVENT_TYPE, DIVISION, DOMAIN, SEGMENT, _AIRBYTE_EXTRACTED_AT AS AIRBYTE_DATE
    FROM {{ ref('sat_bh4sf_match_bvv_curr') }}
    WHERE FIRST_CLIENT_INTERVIEW_DATE IS NOT NULL
),
EVENT_COUNTS AS (
    SELECT
        MATCH_HKEY,
        AIRBYTE_DATE,
        FACT_DATE,
        SUM(CASE WHEN EVENT_TYPE = 'SUBMITTED_TO_AE' THEN 1 ELSE 0 END) AS SUBMITTED_TO_AE,
        SUM(CASE WHEN EVENT_TYPE = 'SUBMITTED_TO_HM' THEN 1 ELSE 0 END) AS SUBMITTED_TO_HM,
        SUM(CASE WHEN EVENT_TYPE = 'FIRST_CLIENT_INTERVIEW' THEN 1 ELSE 0 END) AS FIRST_CLIENT_INTERVIEW,
        DIVISION,
        DOMAIN,
        SEGMENT
    FROM ALL_EVENTS
    GROUP BY MATCH_HKEY, FACT_DATE, AIRBYTE_DATE, DIVISION, DOMAIN, SEGMENT
)
SELECT 
    MATCH_HKEY,
    AIRBYTE_DATE,
    FACT_DATE,
    SUBMITTED_TO_AE,
    SUBMITTED_TO_HM,
    FIRST_CLIENT_INTERVIEW,
    DIVISION,
    DOMAIN,
    SEGMENT
FROM EVENT_COUNTS